INSERT INTO public.tags ("id", "user_id", "name", "color", "created_at", "account_id") VALUES ('00b7e3d1-de63-4b62-aa94-00d541ef883f', 'cdbde4eb-39df-4b27-b345-ce8eae74bbf5', '__lead_routing_config__', '{"enabled":true,"assignmentMethod":"round_robin","notifyAdmin":true,"notifyExecutive":true,"notifyCustomer":true,"adminRecipients":[{"id":"admin-md-sir","name":"MD","phone":"917010469614","active":true},{"id":"admin-1790056772483","name":"GM","phone":"916382624058","active":true},{"id":"admin-1790056786723","name":"AGM","phone":"919994440905","active":true}],"executives":[{"id":"exec-subash","name":"SUBASH","tamilName":"சுபாஷ்","phone":"919384225223","profile_id":"7467ba31-21e8-4983-b475-c7a273486411","user_id":"b8db6f80-377c-41b9-bc79-458ed7733230","active":true,"role":"Sales Executive","languages":["hi","en"],"priority":1},{"id":"exec-satheesh","name":"SATHEESH","tamilName":"சதீஷ்","phone":"919786390479","profile_id":"fac4a28c-d56f-4f22-979c-b288cbdddaae","user_id":"a09eac1f-b95b-4a8c-8c4f-cc5822b32ea1","active":true,"role":"Sales Executive","languages":["ta"],"priority":2},{"id":"exec-bala","name":"BALA","tamilName":"பாலா","phone":"919345232209","profile_id":"1c245b47-b1d2-4de4-a717-03ff249a308d","user_id":"35760e9c-b82a-40d0-a6ee-ca1804d72a90","active":true,"role":"Sales Executive","languages":["te","hi"],"priority":3},{"id":"exec-nallakaman","name":"NALLAKAMAN","tamilName":"நல்லகாமன்","phone":"918925865837","profile_id":"012ae00b-7f53-4c82-b5e9-fbed4ffb8c6d","user_id":"bc6a28a6-7f3c-4ba2-974e-072b192e6c02","active":true,"role":"Sales Executive","languages":["ta"],"priority":4},{"id":"exec-baskar","name":"BASKAR","tamilName":"பாஸ்கர்","phone":"919043978194","profile_id":"8b6f940b-e148-4261-a300-af35e8426bf2","user_id":"a909751b-7022-4e47-aaed-c7cfc5acd526","active":true,"role":"Sales Executive","languages":["kn","en"],"priority":5},{"id":"exec-karthick","name":"KARTHICK","tamilName":"கார்த்திக்","phone":"917603830507","profile_id":"85f11697-ecc9-4447-ab69-8296421f144a","user_id":"944ed513-3b24-4daf-a159-66b37b63a967","active":true,"role":"Sales Executive","languages":["hi","te"],"priority":6}],"slaMinutes":5,"lastAssignedIndex":0,"executiveAlertTemplate":"🚨 *NEW LEAD ASSIGNED TO YOU! | புதிய லீட் உங்களுக்கு ஒதுக்கப்பட்டுள்ளது!*\n\n👤 *Customer / வாடிக்கையாளர்:* {{customer_name}}\n📱 *Phone / எண்:* +{{customer_phone}}\n🏭 *Requirement / தேவை:* {{requirement}}\n📍 *Location / இடம்:* {{location}}\n💬 *Message / தகவல்:* \"{{customer_message}}\"\n⏰ *Time:* {{time}}\n⚡ *URGENT ACTION REQUIRED | உடனடி நடவடிக்கை தேவை:*\nதயவுசெய்து இந்த வாடிக்கையாளரை அடுத்த {{sla_minutes}} நிமிடங்களுக்குள் WhatsApp அல்லது Call செய்து பேசவும்!\n(Please contact this customer within {{sla_minutes}} minutes without delay!)\n\n👉 *Click to WhatsApp / வாட்ஸ்அப் செய்ய:*\nhttps://wa.me/{{customer_phone}}\n\n📞 *Click to Call / போன் செய்ய:*\ntel:+{{customer_phone}}\n\n💻 *Open in CRM Portal:*\n{{crm_inbox_link}}\n\n- *Sri Lakshmi Industries Sales Management*","adminAlertTemplate":"🔥 *NEW LEAD ALERT - Sri Lakshmi Industries*\n\n👤 *Customer:* {{customer_name}}\n📱 *Phone:* +{{customer_phone}}\n🏭 *Requirement:* {{requirement}}\n📍 *Location:* {{location}}\n💬 *Message:* \"{{customer_message}}\"\n━\n🎯 *Assigned Executive:* {{executive_name}} (+{{executive_phone}})\n⏰ *Time:* {{time}} (IST)\n⚡ *SLA:* Call within {{sla_minutes}} mins\n🔗 *CRM Inbox:* {{crm_inbox_link}}","customerWelcomeTemplate":"வணக்கம்! 🙏 *Sri Lakshmi Industries*-க்கு தங்களை அன்போடு வரவேற்கிறோம்! 🌾\n(முன்னணி வணிக ரீதியான முறுக்கு மெஷின் தயாரிப்பாளர்)\n🏆 20+ வருடங்களின் தயாரிப்பு அனுபவம்\n💎 4,000+ திருப்திகரமான வாடிக்கையாளர்கள்\n🚀 1,000+ புதிய உணவுத் தொழில் முனைவோர்கள் (Startups)!\n───────────────────\nWelcome to *Sri Lakshmi Industries*! 🙏🌾\n(Leading Manufacturer of Commercial Murukku Machines)\n🏆 20+ Years of Manufacturing Excellence\n💎 4,000+ Happy Customers Worldwide\n🚀 1,000+ Successful Food Startups Created!\n───────────────────\nనమస్కారం! *శ్రీ లక్ష్మి ఇండస్ట్రీస్ (Sri Lakshmi Industries)* కు స్వాగతం! 🙏🌾\n(కమర్షియల్ మురుకు తయారీ మెషీన్ల ప్రముఖ తయారీదారు)\n🏆 20+ సంవత్సరాల తయారీ అనుభవం\n💎 4,000+ పైగా సంతృప్తి చెందిన కస్టమర్లు\n🚀 1,000+ పైగా విజయవంతమైన కొత్త స్టార్టప్‌లు!\n───────────────────\nനമസ്കാരം! *ശ്രീ ലക്ഷ്മി ഇൻഡസ്ട്രീസിലേക്ക് (Sri Lakshmi Industries)* സ്വാഗതം! 🙏🌾\n(കൊമേഴ്സ്യൽ മുറുക്ക് നിർമ്മാണ മെഷീനുകളുടെ പ്രമുഖ നിർമ്മാതാക്കൾ)\n🏆 20+ വർഷത്തെ നിർമ്മാണ പരിചയം\n💎 4,000+ സംതൃപ്തരായ ഉപഭോക്താക്കൾ\n🚀 1,000+ വിജയകരമായ പുതിയ സംരംഭങ്ങൾ!\n───────────────────\nनमस्ते! *श्री लक्ष्मी इंडस्ट्रीज (Sri Lakshmi Industries)* में आपका स्वागत है! 🙏🌾\n(कमर्शियल मुरुक्कू मेकिंग मशीन के अग्रणी निर्माता)\n🏆 20+ वर्षों का निर्माण अनुभव\n💎 4,000+ संतुष्ट ग्राहक\n🚀 1,000+ सफल नए फूड स्टार्टअप्स!\n───────────────────\n🌐 *Official Website:* https://www.srilakshmiindustries.com\n📺 *YouTube Demo Videos:* https://youtube.com/@murukkumachineprakashsrila833\n📞 *Direct Helpline / Assigned Executive:* +{{executive_phone}} ({{executive_name}})\n\nOur sales executive will call you directly in a few minutes! / எங்கள் விற்பனை பிரதிநிதி விரைவில் உங்களை நேரடி அழைப்பில் தொடர்பு கொள்வார்! 🙏","multilingualCustomerTemplates":{"all_in_one":"வணக்கம்! 🙏 *Sri Lakshmi Industries*-க்கு தங்களை அன்போடு வரவேற்கிறோம்! 🌾\n(முன்னணி வணிக ரீதியான முறுக்கு மெஷின் தயாரிப்பாளர்)\n🏆 20+ வருடங்களின் தயாரிப்பு அனுபவம்\n💎 4,000+ திருப்திகரமான வாடிக்கையாளர்கள்\n🚀 1,000+ புதிய உணவுத் தொழில் முனைவோர்கள் (Startups)!\n───────────────────\nWelcome to *Sri Lakshmi Industries*! 🙏🌾\n(Leading Manufacturer of Commercial Murukku Machines)\n🏆 20+ Years of Manufacturing Excellence\n💎 4,000+ Happy Customers Worldwide\n🚀 1,000+ Successful Food Startups Created!\n───────────────────\nనమస్కారం! *శ్రీ లక్ష్మి ఇండస్ట్రీస్ (Sri Lakshmi Industries)* కు స్వాగతం! 🙏🌾\n(కమర్షియల్ మురుకు తయారీ మెషీన్ల ప్రముఖ తయారీదారు)\n🏆 20+ సంవత్సరాల తయారీ అనుభవం\n💎 4,000+ పైగా సంతృప్తి చెందిన కస్టమర్లు\n🚀 1,000+ పైగా విజయవంతమైన కొత్త స్టార్టప్‌లు!\n───────────────────\nനമസ്കാരം! *ശ്രീ ലക്ഷ്മി ഇൻഡസ്ട്രീസിലേക്ക് (Sri Lakshmi Industries)* സ്വാഗതം! 🙏🌾\n(കൊമേഴ്സ്യൽ മുറുക്ക് നിർമ്മാണ മെഷീനുകളുടെ പ്രമുഖ നിർമ്മാതാക്കൾ)\n🏆 20+ വർഷത്തെ നിർമ്മാണ പരിചയം\n💎 4,000+ സംതൃപ്തരായ ഉപഭോക്താക്കൾ\n🚀 1,000+ വിജയകരമായ പുതിയ സംരംഭങ്ങൾ!\n───────────────────\nनमस्ते! *श्री लक्ष्मी इंडस्ट्रीज (Sri Lakshmi Industries)* में आपका स्वागत है! 🙏🌾\n(कमर्शियल मुरुक्कू मेकिंग मशीन के अग्रणी निर्माता)\n🏆 20+ वर्षों का निर्माण अनुभव\n💎 4,000+ संतुष्ट ग्राहक\n🚀 1,000+ सफल नए फूड स्टार्टअप्स!\n───────────────────\n🌐 *Official Website:* https://www.srilakshmiindustries.com\n📺 *YouTube Demo Videos:* https://youtube.com/@murukkumachineprakashsrila833\n📞 *Direct Helpline / Assigned Executive:* +{{executive_phone}} ({{executive_name}})\n\nOur sales executive will call you directly in a few minutes! / எங்கள் விற்பனை பிரதிநிதி விரைவில் உங்களை நேரடி அழைப்பில் தொடர்பு கொள்வார்! 🙏","ta":"வணக்கம் {{customer_name}}! 🙏✨\n*ஸ்ரீ லக்ஷ்மி இண்டஸ்ட்ரீஸ் (Sri Lakshmi Industries)*-க்கு தங்களை அன்புடன் வரவேற்கிறோம்! 🏭🌾\n\nமுறுக்கு மெஷின் சம்மந்தமாக உங்கள் அனைத்து கேள்விகளுக்கும் எங்கள் விற்பனை பிரதிநிதி *{{executive_name}}* நியமிக்கப்பட்டுள்ளார். உங்களை விரைவில் தொடர்பு கொள்வார் அல்லது இப்போது அவரை அழைக்க கீழே உள்ள பட்டனை / லிங்கை கிளிக் செய்யவும்:\n\n👤 விற்பனை பிரதிநிதி: {{executive_name}}\n📞 தொடர்பு எண்: +{{executive_phone}}\n💬 WhatsApp: https://wa.me/{{executive_phone}}\n📞 Direct Call: tel:+{{executive_phone}}\n\n- *ஸ்ரீ லக்ஷ்மி இண்டஸ்ட்ரீஸ், மதுரை*","en":"Hello {{customer_name}}! 🙏✨\nWelcome to *Sri Lakshmi Industries*! 🏭🌾\n\nOur sales executive *{{executive_name}}* has been assigned to assist you with all your queries regarding Murukku & Food Processing Machines. They will contact you shortly, or click below to connect right away:\n\n👤 Sales Executive: {{executive_name}}\n📞 Contact Number: +{{executive_phone}}\n💬 WhatsApp Chat: https://wa.me/{{executive_phone}}\n📞 Direct Call: tel:+{{executive_phone}}\n\n- *Sri Lakshmi Industries, Madurai*","hi":"नमस्ते {{customer_name}}! 🙏✨\n*श्री लक्ष्मी इंडस्ट्रीज (Sri Lakshmi Industries)* में आपका हार्दिक स्वागत है! 🏭🌾\n\nमुरुक्कु और खाद्य प्र